"""The sound audit, part 3: the world's places and ambience (SPEC §66.5): caves, the land's wind, the wild's plants,
far happenings, rifts and stars, the special places' one-shots, the city's working sounds, the Hearth.

All of it was synthesised (audio_underlife.py, audio_caves.py, audio_lands.py, audio_wild_plants.py, audio_world.py,
audio_amb.py, audio_city_life.py, audio_hearth.py, audio_wilds.py, audio_edge_hold.py): filtered noise for wind and water,
sine partials for hums and chimes. Each is now one of the game's own recordings of the real thing. A looped bed takes
a recording the game itself loops (its water, its portal, a beacon, a minecart rolling, the elytra's wind).
"""
from audit_kit import E, F, group, row

G = group("world", "The world's places and ambience",
          "Caves, wind, water, far happenings, rifts and fallen stars, the special places, the city at work, the Hearth.")


def r(id, module, name, where, was, why, *picks, scene="alone"):
    return row(id, module, G, name, where, "ours, synthesised (" + was + ")", why, list(picks), scene=scene)


